// Package text holds small string helpers.
package text

import "strings"

// Words splits text on whitespace.
func Words(s string) []string {
	return strings.Fields(s)
}

// Wrap wraps text into lines of at most `width` characters, breaking only at spaces.
func Wrap(text string, width int) []string {
	if width <= 0 {
		return nil
	}

	fields := strings.Fields(text)
	if len(fields) == 0 {
		return nil
	}

	lines := []string{fields[0]}
	for _, word := range fields[1:] {
		candidate := lines[len(lines)-1] + " " + word
		if len(candidate) > width {
			lines = append(lines, word)
		} else {
			lines[len(lines)-1] = candidate
		}
	}
	return lines
}

package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name   string
		text   string
		width  int
		want   []string
	}{
		{
			name:  "nil for non-positive width",
			text:  "hello world",
			width: 0,
			want:  nil,
		},
		{
			name:  "nil for negative width",
			text:  "hello world",
			width: -5,
			want:  nil,
		},
		{
			name:  "empty string",
			text:  "",
			width: 10,
			want:  nil,
		},
		{
			name:  "whitespace-only input",
			text:  "   \t\n  ",
			width: 10,
			want:  nil,
		},
		{
			name:  "single word fits",
			text:  "hello",
			width: 10,
			want:   []string{"hello"},
		},
		{
			name:  "simple wrap",
			text:  "the quick brown fox",
			width: 10,
			want:   []string{"the quick", "brown fox"},
		},
		{
			name:  "word longer than width",
			text:  "superlongshort",
			width: 5,
			want:   []string{"superlongshort"},
		},
		{
			name:  "multiple long words",
			text:  "abcdefgh ijklmnop",
			width: 5,
			want:   []string{"abcdefgh", "ijklmnop"},
		},
		{
			name:  "collapses whitespace",
			text:  "a    b\tc\n d",
			width: 20,
			want:   []string{"a b c d"},
		},
		{
			name:  "no trailing or leading spaces",
			text:  "  hello world  ",
			width: 10,
			want:   []string{"hello", "world"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if len(got) == 0 && got == nil && tt.want == nil {
				return // both nil — match
			}
			if len(got) == 0 && tt.want == nil {
				return // empty slice when nil expected is fine
			}
			if tt.want == nil && got != nil {
				t.Fatalf("want nil, got %v", got)
			}
			if len(got) != len(tt.want) {
				t.Fatalf("got %d lines, want %d: %v", len(got), len(tt.want), got)
			}
			for i, w := range tt.want {
				if got[i] != w {
					t.Errorf("line %d: got %q, want %q", i, got[i], w)
				}
				if len(got[i]) > tt.width {
					t.Errorf("line %q has length %d > width %d", got[i], len(got[i]), tt.width)
				}
			}
		})
	}
}

